const mapOperation=(row:Row):TransferOperation=>({id:String(row.id),spaceId:String(row.space_id),bookId:asText(row.book_id),operationKind:row.operation_kind as TransferOperation["operationKind"],executionMode:row.execution_mode as TransferOperation["executionMode"],profileKey:row.profile_key as TransferProfileKey,sourceOperationId:asText(row.source_operation_id),sourceArtifactId:asText(row.source_artifact_id),targetStagingKey:String(row.target_staging_key),status:row.status as TransferOperationStatus,currentStepKey:String(row.current_step_key),progressCompleted:Number(row.progress_completed),progressTotal:row.progress_total===null?null:Number(row.progress_total),readyManifestId:asText(row.ready_manifest_id),compatibilityPolicy:row.compatibility_policy as TransferOperation["compatibilityPolicy"],maxEntryCount:Number(row.max_entry_count),maxSingleFileBytes:Number(row.max_single_file_bytes),maxTotalBytes:Number(row.max_total_bytes),maxCompressionRatio:Number(row.max_compression_ratio),maintenanceModeRequired:Boolean(row.maintenance_mode_required),requestedBy:String(row.requested_by),revision:Number(row.revision),lastErrorCode:String(row.last_error_code),lastErrorSummary:String(row.last_error_summary),createdAt:asDate(row.created_at),startedAt:row.started_at?asDate(row.started_at):null,completedAt:row.completed_at?asDate(row.completed_at):null,archivedAt:row.archived_at?asDate(row.archived_at):null});
const mapManifest=(row:Row):TransferManifest=>({id:String(row.id),operationId:String(row.operation_id),manifestKind:row.manifest_kind as TransferManifest["manifestKind"],formatVersion:Number(row.format_version),applicationVersion:String(row.application_version),minimumApplicationVersion:String(row.minimum_application_version),maximumApplicationVersion:String(row.maximum_application_version),schemaVersion:String(row.schema_version),schemaMigrations:row.schema_migrations as TransferManifest["schemaMigrations"],migrationHash:String(row.migration_hash),postgresVersion:String(row.postgres_version),ageVersion:asText(row.age_version),pgvectorVersion:asText(row.pgvector_version),requiredCapabilities:row.required_capabilities as string[],cardSchemaVersions:row.card_schema_versions as unknown[],formSchemaVersions:row.form_schema_versions as unknown[],templateSchemaVersions:row.template_schema_versions as unknown[],promptSchemaVersions:row.prompt_schema_versions as unknown[],encoding:"UTF8",platformConstraints:row.platform_constraints as Record<string,unknown>,consistencySnapshot:String(row.consistency_snapshot),consistencyWatermark:row.consistency_watermark as Record<string,unknown>,contentScope:row.content_scope as Record<string,unknown>,excludedDerivedDomains:row.excluded_derived_domains as string[],secretReconfigurationRefs:row.secret_reconfiguration_refs as string[],manifestHash:String(row.manifest_hash),createdBy:String(row.created_by),createdAt:asDate(row.created_at)});
const mapArtifact=(row:Row):TransferArtifact=>({id:String(row.id),operationId:String(row.operation_id),manifestId:asText(row.manifest_id),artifactKind:row.artifact_kind as TransferArtifact["artifactKind"],mediaType:String(row.media_type),storageLocator:String(row.storage_locator),displayFilename:String(row.display_filename),checksum:asText(row.checksum),byteSize:row.byte_size===null?null:Number(row.byte_size),entryCount:row.entry_count===null?null:Number(row.entry_count),compressedBytes:row.compressed_bytes===null?null:Number(row.compressed_bytes),uncompressedBytes:row.uncompressed_bytes===null?null:Number(row.uncompressed_bytes),status:row.status as TransferArtifact["status"],errorCode:String(row.error_code),createdAt:asDate(row.created_at),readyAt:row.ready_at?asDate(row.ready_at):null});
const mapArchiveEntry=(row:Row):TransferArchiveEntry=>({id:String(row.id),artifactId:String(row.artifact_id),archivePath:String(row.archive_path),entryKind:row.entry_kind as TransferArchiveEntry["entryKind"],checksum:asText(row.checksum),compressedBytes:Number(row.compressed_bytes),uncompressedBytes:Number(row.uncompressed_bytes),compressionRatio:Number(row.compression_ratio),createdAt:asDate(row.created_at)});
const mapCompatibility=(row:Row):TransferCompatibilitySnapshot=>({id:String(row.id),operationId:String(row.operation_id),sourceFormatVersion:Number(row.source_format_version),sourceApplicationVersion:String(row.source_application_version),currentApplicationVersion:String(row.current_application_version),sourceSchemaVersion:String(row.source_schema_version),currentSchemaVersion:String(row.current_schema_version),sourceMigrationHash:String(row.source_migration_hash),currentMigrationHash:String(row.current_migration_hash),extensionVersions:row.extension_versions as Record<string,unknown>,requiredCapabilities:row.required_capabilities as string[],missingCapabilities:row.missing_capabilities as string[],unknownRequiredCapabilities:row.unknown_required_capabilities as string[],outcome:row.outcome as TransferCompatibilitySnapshot["outcome"],detail:String(row.detail),checkedAt:asDate(row.checked_at)});
const mapStep=(row:Row):TransferStep=>({id:String(row.id),operationId:String(row.operation_id),stepKey:String(row.step_key),sortOrder:Number(row.sort_order),status:row.status as TransferStep["status"],progressCompleted:Number(row.progress_completed),progressTotal:row.progress_total===null?null:Number(row.progress_total),checkpointKey:String(row.checkpoint_key),errorCode:String(row.error_code),errorSummary:String(row.error_summary),revision:Number(row.revision),createdAt:asDate(row.created_at),startedAt:row.started_at?asDate(row.started_at):null,completedAt:row.completed_at?asDate(row.completed_at):null});
const mapCheckpoint=(row:Row):TransferCheckpoint=>({id:String(row.id),operationId:String(row.operation_id),stepId:String(row.step_id),checkpointKey:String(row.checkpoint_key),checkpointData:row.checkpoint_data as Record<string,unknown>,checkpointHash:String(row.checkpoint_hash),createdAt:asDate(row.created_at)});
