const mapConflict=(row:Row):TransferConflict=>({id:String(row.id),operationId:String(row.operation_id),conflictKind:row.conflict_kind as TransferConflict["conflictKind"],entityKind:String(row.entity_kind),portableKey:String(row.portable_key),sourceVersion:String(row.source_version),targetVersion:String(row.target_version),status:row.status as TransferConflict["status"],resolution:row.resolution as TransferConflict["resolution"],resolutionNote:String(row.resolution_note),revision:Number(row.revision),createdAt:asDate(row.created_at),resolvedAt:row.resolved_at?asDate(row.resolved_at):null});
const mapIdMapping=(row:Row):TransferIdMapping=>({id:String(row.id),operationId:String(row.operation_id),entityKind:String(row.entity_kind),portableKey:String(row.portable_key),sourceInternalId:asText(row.source_internal_id),targetInternalId:String(row.target_internal_id),mappingAction:row.mapping_action as TransferIdMapping["mappingAction"],targetVersion:String(row.target_version),createdAt:asDate(row.created_at)});
const mapStaging=(row:Row):TransferStagingScope=>({id:String(row.id),operationId:String(row.operation_id),stagingKind:row.staging_kind as TransferStagingScope["stagingKind"],stagingKey:String(row.staging_key),status:row.status as TransferStagingScope["status"],targetSpaceId:asText(row.target_space_id),targetBookId:asText(row.target_book_id),revision:Number(row.revision),createdAt:asDate(row.created_at),publishedAt:row.published_at?asDate(row.published_at):null,abandonedAt:row.abandoned_at?asDate(row.abandoned_at):null});
const mapImportSource=(row:Row):TransferImportSource=>({id:String(row.id),operationId:String(row.operation_id),sourceArtifactId:String(row.source_artifact_id),sourceManifestId:String(row.source_manifest_id),sourceInstallationHash:String(row.source_installation_hash),sourceOperationKey:String(row.source_operation_key),importedBy:String(row.imported_by),createdAt:asDate(row.created_at)});
