async function tx<T>(run:(client:PoolClient)=>Promise<T>):Promise<T>{const pool=await getNewDesignPool(),client=await pool.connect();try{await client.query("BEGIN");const value=await run(client);await client.query("COMMIT");return value;}catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}}
const clean=(value:string,max:number)=>value.replace(/(api[_-]?key|token|password|secret|credential|database[_-]?url|authorization|cookie|set-cookie)\s*[:=]\s*\S+/gi,"$1=[redacted]").replace(/\bBearer\s+\S+/gi,"Bearer [redacted]").replace(/([?&](?:token|signature|x-amz-credential|x-amz-signature)=)[^&\s]+/gi,"$1[redacted]").slice(0,max);

const stepPlans:Record<TransferOperationKind,string[]>= {
  full_backup:["preflight","freeze_snapshot","database_dump","asset_inventory","package","verify"],
  full_restore:["preflight","scan_archive","compatibility","allocate_staging","restore_database","restore_assets","verify_staging","publish"],
  book_export:["preflight","freeze_snapshot","collect_book","collect_assets","package","verify"],
  book_import:["preflight","scan_archive","compatibility","resolve_ids","allocate_staging","import_book","verify_staging","publish"],
  template_export:["preflight","collect_templates","package","verify"],
  template_import:["preflight","scan_archive","compatibility","resolve_ids","allocate_staging","import_templates","verify_staging","publish"],
  resource_export:["preflight","collect_resources","package","verify"],
  resource_import:["preflight","scan_archive","compatibility","resolve_ids","allocate_staging","import_resources","verify_staging","publish"],
};

async function insertInitialSteps(client:PoolClient,operationId:string,kind:TransferOperationKind):Promise<void>{let order=0;for(const key of stepPlans[kind]){await (async()=>{const values={id:randomUUID(),operation_id:operationId,step_key:key,sort_order:order,status:"queued",progress_completed:0,progress_total:null,checkpoint_key:"",error_code:"",error_summary:"",revision:1,created_at:new Date().toISOString(),started_at:null,completed_at:null};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE',[values.operation_id])).rows[0],'传输操作不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"transfer_step",title:"transfer_step",values});return{rows:[row],rowCount:1};})();order+=10;}}
async function insertEvent(client:PoolClient,operationId:string,from:TransferOperationStatus|null,to:TransferOperationStatus,action:TransferOperationEvent["action"],actor:string,detail:string,revision:number):Promise<void>{await client.query("INSERT INTO new_design.transfer_events(id,operation_id,from_status,to_status,action,actor,detail,operation_revision) VALUES($1,$2,$3,$4,$5,$6,$7,$8)",[randomUUID(),operationId,from,to,action,actor,clean(detail,2000),revision]);}

export async function listTransferProfiles():Promise<TransferExportProfile[]>{const pool=await getNewDesignPool();return(await pool.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_export_profile' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(profile_key text,package_kind text,description text,included_domains jsonb,excluded_domains jsonb,include_version_history boolean,include_runtime_evidence boolean,status text,created_at timestamptz) WHERE record.status='active') transfer_export_profile_record WHERE status='active' ORDER BY profile_key")).rows.map(mapProfile);}

export async function createTransferOperationRecord(input:{operationKind:Extract<TransferOperationKind,"full_backup"|"book_export"|"template_export"|"resource_export">;profileKey:TransferProfileKey;bookId?:string|null;requestedBy:string;idempotencyKey:string}):Promise<TransferOperationDetail>{return tx(async client=>{let spaceId=SYSTEM_SPACE_ID;if(input.bookId){const book=assertFound((await client.query("SELECT space_id FROM new_design.books WHERE id=$1",[input.bookId])).rows[0],"导出的书籍不存在。");spaceId=String(book.space_id);}const existing=(await client.query("SELECT * FROM new_design.transfer_operations WHERE space_id=$1 AND idempotency_key=$2",[spaceId,input.idempotencyKey])).rows[0];if(existing){if(existing.operation_kind!==input.operationKind||existing.profile_key!==input.profileKey||asText(existing.book_id)!==(input.bookId??null))throw new NewDesignError("相同传输幂等键对应了不同请求。",409);return getTransferOperationWith(client,String(existing.id));}const id=randomUUID(),row=(await client.query("INSERT INTO new_design.transfer_operations(id,space_id,book_id,operation_kind,execution_mode,profile_key,target_staging_key,requested_by,idempotency_key) VALUES($1,$2,$3,$4,'execute',$5,$6,$7,$8) RETURNING *",[id,spaceId,input.bookId??null,input.operationKind,input.profileKey,`transfer-${id.replaceAll("-","")}`,input.requestedBy,input.idempotencyKey])).rows[0];await insertInitialSteps(client,id,input.operationKind);await insertEvent(client,id,null,"queued","request",input.requestedBy,"传输操作已登记，等待受控后台运行器。",1);return getTransferOperationWith(client,String(row.id));});}

export async function createImportDryRunRecord(input:{operationKind:Extract<TransferOperationKind,"full_restore"|"book_import"|"template_import"|"resource_import">;profileKey:TransferProfileKey;requestedBy:string;idempotencyKey:string;source:{storageLocator:string;displayFilename:string;mediaType:string;checksum:string;byteSize:number;entryCount:number;compressedBytes:number;uncompressedBytes:number}}):Promise<TransferOperationDetail>{if(!input.source.displayFilename.trim()||/[\\/]/.test(input.source.displayFilename)||!/^[a-f0-9]{64}$/.test(input.source.checksum))throw new NewDesignError("导入票据中的文件名或 SHA-256 无效。",422);return tx(async client=>{const existing=(await client.query("SELECT * FROM new_design.transfer_operations WHERE space_id=$1 AND idempotency_key=$2",[SYSTEM_SPACE_ID,input.idempotencyKey])).rows[0];if(existing){if(existing.operation_kind!==input.operationKind||existing.profile_key!==input.profileKey)throw new NewDesignError("相同传输幂等键对应了不同导入预检。",409);return getTransferOperationWith(client,String(existing.id));}const operationId=randomUUID(),artifactId=randomUUID(),locator=normalizePortableLocator(input.source.storageLocator);await client.query("INSERT INTO new_design.transfer_operations(id,space_id,operation_kind,execution_mode,profile_key,source_artifact_id,target_staging_key,requested_by,idempotency_key) VALUES($1,$2,$3,'dry_run',$4,$5,$6,$7,$8)",[operationId,SYSTEM_SPACE_ID,input.operationKind,input.profileKey,artifactId,`transfer-${operationId.replaceAll("-","")}`,input.requestedBy,input.idempotencyKey]);await (async()=>{const values={id:artifactId,operation_id:operationId,manifest_id:null,artifact_kind:"package",media_type:input.source.mediaType,storage_locator:locator,normalized_case_locator:locator.toLowerCase(),display_filename:input.source.displayFilename,checksum_algorithm:"sha256",checksum:input.source.checksum,byte_size:input.source.byteSize,entry_count:input.source.entryCount,compressed_bytes:input.source.compressedBytes,uncompressed_bytes:input.source.uncompressedBytes,status:"pending",error_code:"",created_at:new Date().toISOString(),ready_at:null};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE',[values.operation_id])).rows[0],'传输操作不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"transfer_artifact",title:"transfer_artifact",values});return{rows:[row],rowCount:1};})();await insertInitialSteps(client,operationId,input.operationKind);await insertEvent(client,operationId,null,"queued","request",input.requestedBy,"导入预检已登记，原包只在隔离区读取。",1);return getTransferOperationWith(client,operationId);});}

export async function confirmImportRecord(dryRunId:string,input:{requestedBy:string;idempotencyKey:string;compatibilityPolicy:"strict"|"explicit_upgrade"}):Promise<TransferOperationDetail>{return tx(async client=>{const source=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 AND execution_mode='dry_run' AND status='ready' FOR UPDATE",[dryRunId])).rows[0],"导入预检尚未 ready 或不存在。");if(source.operation_kind==="full_restore")throw new NewDesignError("整库恢复必须使用本机维护模式入口。",403);if((await client.query("SELECT 1 FROM new_design.transfer_conflicts WHERE operation_id=$1 AND status IN ('pending','blocking')",[dryRunId])).rowCount)throw new NewDesignError("仍有未解决的导入冲突。",409);const existing=(await client.query("SELECT * FROM new_design.transfer_operations WHERE space_id=$1 AND idempotency_key=$2",[source.space_id,input.idempotencyKey])).rows[0];if(existing){if(existing.source_operation_id!==dryRunId||existing.operation_kind!==source.operation_kind||existing.execution_mode!=="apply")throw new NewDesignError("相同传输幂等键对应了不同导入请求。",409);return getTransferOperationWith(client,String(existing.id));}const id=randomUUID();await client.query("INSERT INTO new_design.transfer_operations(id,space_id,operation_kind,execution_mode,profile_key,source_operation_id,source_artifact_id,target_staging_key,compatibility_policy,requested_by,idempotency_key) VALUES($1,$2,$3,'apply',$4,$5,$6,$7,$8,$9,$10)",[id,source.space_id,source.operation_kind,source.profile_key,source.id,source.source_artifact_id,`transfer-${id.replaceAll("-","")}`,input.compatibilityPolicy,input.requestedBy,input.idempotencyKey]);await insertInitialSteps(client,id,source.operation_kind as TransferOperationKind);await insertEvent(client,id,null,"queued","request",input.requestedBy,"已依据明确的预检结果创建隔离导入操作。",1);return getTransferOperationWith(client,id);});}

export async function confirmRestoreRecord(dryRunId:string,input:{requestedBy:string;idempotencyKey:string;localConfirmationDigest:string;maintenanceModeConfirmed:boolean;localElevationConfirmed:boolean}):Promise<TransferOperationDetail>{if(!input.maintenanceModeConfirmed||!input.localElevationConfirmed||!/^[a-f0-9]{64}$/.test(input.localConfirmationDigest))throw new NewDesignError("整库恢复需要维护模式和本机高权限确认。",403);return tx(async client=>{const source=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 AND operation_kind='full_restore' AND execution_mode='dry_run' AND status='ready' FOR UPDATE",[dryRunId])).rows[0],"恢复预检尚未 ready 或不存在。"),existing=(await client.query("SELECT * FROM new_design.transfer_operations WHERE space_id=$1 AND idempotency_key=$2",[source.space_id,input.idempotencyKey])).rows[0];if(existing){if(existing.source_operation_id!==dryRunId||existing.operation_kind!=="full_restore"||existing.execution_mode!=="apply")throw new NewDesignError("相同传输幂等键对应了不同恢复请求。",409);return getTransferOperationWith(client,String(existing.id));}const id=randomUUID();await client.query("INSERT INTO new_design.transfer_operations(id,space_id,operation_kind,execution_mode,profile_key,source_operation_id,source_artifact_id,target_staging_key,compatibility_policy,maintenance_mode_required,local_confirmation_digest,requested_by,idempotency_key) VALUES($1,$2,'full_restore','apply','full_system',$3,$4,$5,'strict',true,$6,$7,$8)",[id,source.space_id,source.id,source.source_artifact_id,`transfer-${id.replaceAll("-","")}`,input.localConfirmationDigest,input.requestedBy,input.idempotencyKey]);await insertInitialSteps(client,id,"full_restore");await insertEvent(client,id,null,"queued","request",input.requestedBy,"维护模式恢复操作已登记，只能写入全新 staging。",1);return getTransferOperationWith(client,id);});}

