export async function getTransferOperation(id:string):Promise<TransferOperationDetail>{const pool=await getNewDesignPool(),client=await pool.connect();try{return await getTransferOperationWith(client,id);}finally{client.release();}}
export async function listTransferOperations(input:{bookId?:string;status?:TransferOperationStatus;limit:number}):Promise<TransferOperation[]>{const pool=await getNewDesignPool();return(await pool.query("SELECT * FROM new_design.transfer_operations WHERE ($1::uuid IS NULL OR book_id=$1) AND ($2::text IS NULL OR status=$2) ORDER BY created_at DESC,id DESC LIMIT $3",[input.bookId??null,input.status??null,input.limit])).rows.map(mapOperation);}

export async function cancelTransferOperation(id:string,input:{reason:string;actor:string;expectedRevision:number}):Promise<TransferOperationDetail>{return tx(async client=>{const operation=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[id])).rows[0],"传输操作不存在。");if(Number(operation.revision)!==input.expectedRevision||!["queued","running","verifying"].includes(String(operation.status)))throw new NewDesignError("传输操作已变化或不能取消。",409);const job=assertFound((await client.query("SELECT id FROM new_design.background_jobs WHERE specialized_request_kind='backup_request' AND specialized_request_id=$1 AND execution_generation=1",[id])).rows[0],"传输后台作业不存在。");await requestBackgroundJobCancellationWith(client,String(job.id),input.reason);const revision=Number(operation.revision)+1,row=(await client.query("UPDATE new_design.transfer_operations SET status='cancelled',revision=$2,last_error_code='operator_cancel',last_error_summary=$3,completed_at=now() WHERE id=$1 RETURNING *",[id,revision,clean(input.reason,2000)])).rows[0];await (async()=>{const rows=[];for(const current of await listRecordCards(client,"transfer_staging_scope",{lock:true,where:{operation_id:id}})){if(!(current.operation_id===(id)&&["allocated","validating","ready_to_publish"].includes(String(current.status))))continue;const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"transfer_staging_scope",values:{...current,updated_at:new Date().toISOString(),status:"abandoned",revision:Number(current.revision)+1,abandoned_at:new Date().toISOString()}});rows.push(row);}return{rows,rowCount:rows.length};})();await insertEvent(client,id,operation.status as TransferOperationStatus,"cancelled","cancel",input.actor,input.reason,revision);return getTransferOperationWith(client,String(row.id));});}

export async function resolveTransferConflict(id:string,input:{resolution:NonNullable<TransferConflict["resolution"]>;resolutionNote:string;expectedRevision:number}):Promise<TransferConflict>{const pool=await getNewDesignPool(),row=(await pool.query("UPDATE new_design.transfer_conflicts SET status='resolved',resolution=$2,resolution_note=$3,revision=revision+1,resolved_at=now() WHERE id=$1 AND revision=$4 AND status IN ('pending','blocking') RETURNING *",[id,input.resolution,clean(input.resolutionNote,2000),input.expectedRevision])).rows[0];if(!row)throw new NewDesignError("导入冲突已变化或不可处理。",409);return mapConflict(row);}

export async function getReadyTransferArtifact(id:string):Promise<TransferArtifact>{const pool=await getNewDesignPool(),row=assertFound((await pool.query("SELECT artifact.* FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_artifact' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,manifest_id uuid,artifact_kind text,media_type text,storage_locator text,normalized_case_locator text,display_filename text,checksum_algorithm text,checksum char(64),byte_size bigint,entry_count integer,compressed_bytes bigint,uncompressed_bytes bigint,status text,error_code text,created_at timestamptz,ready_at timestamptz) WHERE record.status='active') artifact JOIN new_design.transfer_operations operation ON operation.id=artifact.operation_id WHERE artifact.id=$1 AND artifact.artifact_kind='package' AND artifact.status='ready' AND operation.status='ready'",[id])).rows[0],"可下载传输包不存在或尚未 ready。");return mapArtifact(row);}

export async function startTransferOperation(id:string,actor:string):Promise<TransferOperation>{return tx(async client=>{const current=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 AND status='queued' FOR UPDATE",[id])).rows[0],"传输操作不在等待状态。"),revision=Number(current.revision)+1,row=(await client.query("UPDATE new_design.transfer_operations SET status='running',started_at=now(),revision=$2,current_step_key='preflight' WHERE id=$1 RETURNING *",[id,revision])).rows[0];await insertEvent(client,id,"queued","running","start",actor,"受控执行器开始处理。",revision);return mapOperation(row);});}
export async function markTransferVerifying(id:string,actor:string):Promise<TransferOperation>{return tx(async client=>{const current=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 AND status='running' FOR UPDATE",[id])).rows[0],"传输操作不在执行状态。"),revision=Number(current.revision)+1,row=(await client.query("UPDATE new_design.transfer_operations SET status='verifying',revision=$2,current_step_key='verify' WHERE id=$1 RETURNING *",[id,revision])).rows[0];await insertEvent(client,id,"running","verifying","verify",actor,"进入完整性与兼容性校验。",revision);return mapOperation(row);});}

export async function recordTransferCheckpoint(input:{operationId:string;stepId:string;checkpointKey:string;checkpointData:Record<string,unknown>}):Promise<TransferCheckpoint>{return tx(async client=>{const operation=assertFound((await client.query("SELECT status FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[input.operationId])).rows[0],"传输操作不存在。");if(!["running","verifying"].includes(String(operation.status)))throw new NewDesignError("只有执行中的传输操作可以保存检查点。",409);const step=await findRecordCard(client,input.stepId,"transfer_step",{lock:true});if(!step||step.operation_id!==input.operationId)throw new NewDesignError("检查点步骤不属于当前传输。",409);const safe=(await client.query("SELECT jsonb_typeof($1::jsonb)='object' AND new_design.transfer_json_is_safe($1::jsonb) AND new_design.outbox_payload_is_reference_only($1::jsonb) AND octet_length(($1::jsonb)::text)<=16384 AS valid",[JSON.stringify(input.checkpointData)])).rows[0];if(!safe?.valid||!input.checkpointKey||input.checkpointKey.length>240)throw new NewDesignError("检查点必须是有界、安全的引用元数据。",422);const hash=stableHash(input.checkpointData),existing=(await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_checkpoint' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,step_id uuid,checkpoint_key text,checkpoint_data jsonb,checkpoint_hash char(64),created_at timestamptz) WHERE record.status='active') transfer_checkpoint_record WHERE operation_id=$1 AND step_id=$2 AND checkpoint_key=$3 AND checkpoint_hash=$4",[input.operationId,input.stepId,input.checkpointKey,hash])).rows[0];if(existing)return mapCheckpoint(existing);if(!["queued","running"].includes(step.status))throw new NewDesignError("完成的步骤不能追加检查点。",409);const row=(await (async()=>{const values={id:randomUUID(),operation_id:input.operationId,step_id:input.stepId,checkpoint_key:input.checkpointKey,checkpoint_data:input.checkpointData,checkpoint_hash:hash,created_at:new Date().toISOString()};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE',[values.operation_id])).rows[0],'传输操作不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"transfer_checkpoint",title:"transfer_checkpoint",values});return{rows:[row],rowCount:1};})()).rows[0];await (async()=>{const rows=[];for(const current of await listRecordCards(client,"transfer_step",{lock:true,where:{id:input.stepId}})){if(!(current.id===(input.stepId)&&["queued","running"].includes(String(current.status))))continue;const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"transfer_step",values:{...current,updated_at:new Date().toISOString(),status:"running",checkpoint_key:input.checkpointKey,revision:Number(current.revision)+1,started_at:(current.started_at)??(new Date().toISOString())}});rows.push(row);}return{rows,rowCount:rows.length};})();return mapCheckpoint(row);});}

export async function advanceTransferStep(id:string,input:{toStatus:"running"|"succeeded"|"failed"|"cancelled"|"skipped";expectedRevision:number;progressCompleted?:number;progressTotal?:number|null;errorCode?:string;errorSummary?:string}):Promise<TransferStep>{
  const terminal=["succeeded","failed","cancelled","skipped"].includes(input.toStatus),pool=await getNewDesignPool(),row=(await tx(async client=>{const snapshot=await findRecordCard(client,id,"transfer_step");if(!snapshot)return{rows:[]};const operation=(await client.query("SELECT status FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[snapshot.operation_id])).rows[0];const current=await findRecordCard(client,id,"transfer_step",{lock:true});if(!current||Number(current.revision)!==input.expectedRevision)return{rows:[]};if(!operation||!["running","verifying"].includes(String(operation.status)))return{rows:[]};const allowed=current.status==="queued"?["running","skipped","cancelled"]:current.status==="running"?["running","succeeded","failed","cancelled"]:[];if(!allowed.includes(input.toStatus))throw new NewDesignError("传输步骤不能进行此状态转换。",409);if(input.toStatus==="failed"&&(!input.errorCode?.trim()||!input.errorSummary?.trim()))throw new NewDesignError("失败步骤必须说明错误。",422);const progressCompleted=input.progressCompleted??Number(current.progress_completed),progressTotal=input.progressTotal??current.progress_total;if(!Number.isSafeInteger(progressCompleted)||progressCompleted<0||progressTotal!=null&&(!Number.isSafeInteger(Number(progressTotal))||Number(progressTotal)<progressCompleted))throw new NewDesignError("传输进度无效。",422);const row=await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"transfer_step",values:{...current,status:input.toStatus,progress_completed:progressCompleted,progress_total:progressTotal,error_code:clean(input.errorCode??"",120),error_summary:clean(input.errorSummary??"",2000),revision:Number(current.revision)+1,started_at:input.toStatus==="running"?(current.started_at??new Date().toISOString()):current.started_at,completed_at:terminal?new Date().toISOString():null}});return{rows:[row]};})).rows[0];
  if(!row)throw new NewDesignError("传输步骤已变化或操作不在执行状态。",409);
  return mapStep(row);
}

export async function recordArchiveInventory(input:{operationId:string;artifactId:string;entries:Array<ArchiveEntryCandidate&{checksum?:string|null}>}):Promise<number>{return tx(async client=>{const operation=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[input.operationId])).rows[0],"传输操作不存在。"),artifact=assertFound((await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_artifact' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,manifest_id uuid,artifact_kind text,media_type text,storage_locator text,normalized_case_locator text,display_filename text,checksum_algorithm text,checksum char(64),byte_size bigint,entry_count integer,compressed_bytes bigint,uncompressed_bytes bigint,status text,error_code text,created_at timestamptz,ready_at timestamptz) WHERE record.status='active') transfer_artifact_record WHERE id=$1 AND operation_id=$2 FOR UPDATE",[input.artifactId,input.operationId])).rows[0],"传输产物不存在。");if(!["pending","ready"].includes(String(artifact.status))||!["running","verifying"].includes(String(operation.status)))throw new NewDesignError("只有执行中的待验证或输入产物可以登记归档清单。",409);if((await client.query("SELECT 1 FROM new_design.transfer_entries WHERE artifact_id=$1 LIMIT 1",[input.artifactId])).rowCount)throw new NewDesignError("归档清单已经冻结，不能重复登记。",409);const validated=validateArchiveEntries(input.entries,{maxEntryCount:Number(operation.max_entry_count),maxSingleFileBytes:Number(operation.max_single_file_bytes),maxTotalBytes:Number(operation.max_total_bytes),maxCompressionRatio:Number(operation.max_compression_ratio)});for(let index=0;index<validated.length;index+=1){const item=validated[index],checksum=input.entries[index].checksum??null;if(item.kind==="file"&&!/^[a-f0-9]{64}$/.test(checksum??""))throw new NewDesignError("文件条目必须带有效 SHA-256。",422);await client.query("INSERT INTO new_design.transfer_entries(id,artifact_id,archive_path,normalized_case_path,entry_kind,checksum,compressed_bytes,uncompressed_bytes,compression_ratio) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)",[randomUUID(),input.artifactId,item.path,item.normalizedCasePath,item.kind,checksum,item.compressedBytes,item.uncompressedBytes,item.compressionRatio]);}return validated.length;});}

export async function recordTransferValidation(input:Omit<TransferValidationResult,"id"|"createdAt">):Promise<TransferValidationResult>{const pool=await getNewDesignPool(),row=(await pool.query("INSERT INTO new_design.transfer_validations(id,operation_id,stage,rule_key,outcome,subject_kind,subject_ref,detail) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *",[randomUUID(),input.operationId,input.stage,input.ruleKey,input.outcome,input.subjectKind,input.subjectRef,clean(input.detail,4000)])).rows[0];return mapValidation(row);}

