export async function recordTransferImportSource(input:Omit<TransferImportSource,"id"|"createdAt">):Promise<TransferImportSource>{
  if(!/^[a-f0-9]{64}$/.test(input.sourceInstallationHash))throw new NewDesignError("来源安装哈希无效。",422);
  return tx(async client=>{
    const operation=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 AND execution_mode='apply' FOR UPDATE",[input.operationId])).rows[0],"apply 传输操作不存在。");
    if(!["running","verifying"].includes(String(operation.status)))throw new NewDesignError("只有执行中的操作可以冻结导入来源。",409);if(operation.source_artifact_id!==input.sourceArtifactId)throw new NewDesignError("来源产物与预检冻结值不一致。",409);
    const source=assertFound((await client.query("SELECT artifact.id FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_artifact' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,manifest_id uuid,artifact_kind text,media_type text,storage_locator text,normalized_case_locator text,display_filename text,checksum_algorithm text,checksum char(64),byte_size bigint,entry_count integer,compressed_bytes bigint,uncompressed_bytes bigint,status text,error_code text,created_at timestamptz,ready_at timestamptz) WHERE record.status='active') artifact JOIN new_design.transfer_manifests manifest ON manifest.id=$2 AND manifest.operation_id=artifact.operation_id JOIN new_design.transfer_operations preflight ON preflight.id=artifact.operation_id AND preflight.execution_mode='dry_run' AND preflight.status='ready' AND preflight.ready_manifest_id=manifest.id WHERE artifact.id=$1 AND artifact.status='ready' AND preflight.id=$3",[input.sourceArtifactId,input.sourceManifestId,operation.source_operation_id])).rows[0],"来源产物和 manifest 不属于同一预检操作。");
    const existing=(await client.query("SELECT * FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_import_source' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,source_artifact_id uuid,source_manifest_id uuid,source_installation_hash char(64),source_operation_key text,imported_by text,created_at timestamptz) WHERE record.status='active') transfer_import_source_record WHERE operation_id=$1",[input.operationId])).rows[0];if(existing){if(existing.source_artifact_id!==input.sourceArtifactId||existing.source_manifest_id!==input.sourceManifestId||existing.source_installation_hash!==input.sourceInstallationHash||existing.source_operation_key!==input.sourceOperationKey||existing.imported_by!==input.importedBy)throw new NewDesignError("导入来源已经冻结且内容不同。",409);return mapImportSource(existing);}
    return mapImportSource((await (async()=>{const values={id:randomUUID(),operation_id:input.operationId,source_artifact_id:source.id,source_manifest_id:input.sourceManifestId,source_installation_hash:input.sourceInstallationHash,source_operation_key:input.sourceOperationKey,imported_by:input.importedBy,created_at:new Date().toISOString()};const spaceId=String(assertFound((await client.query('SELECT space_id FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE',[values.operation_id])).rows[0],'传输操作不存在。').space_id);const row=await createRecordCard(client,{id:String(values.id),spaceId,typeKey:"transfer_import_source",title:"transfer_import_source",values});return{rows:[row],rowCount:1};})()).rows[0]);
  });
}

export async function recordTransferRestoreDrill(input:Omit<TransferRestoreDrill,"id">):Promise<TransferRestoreDrill>{
  const pool=await getNewDesignPool(),row=(await tx(async client=>{const backup=(await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[input.backupOperationId])).rows[0],drill=(await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[input.drillOperationId])).rows[0];if(!backup||backup.operation_kind!=="full_backup"||!["ready","archived"].includes(String(backup.status))||!drill||drill.operation_kind!=="full_restore"||drill.execution_mode!=="dry_run"||!(drill.status==="ready"&&input.outcome==="passed"||drill.status==="failed"&&["failed","unavailable"].includes(input.outcome)||drill.status==="cancelled"&&input.outcome==="cancelled"))return{rows:[]};if(!Number.isFinite(Date.parse(input.startedAt))||!Number.isFinite(Date.parse(input.completedAt))||Date.parse(input.completedAt)<Date.parse(input.startedAt)||(await client.query("SELECT jsonb_typeof($1::jsonb)='object' AND new_design.transfer_json_is_safe($1::jsonb) AS valid",[JSON.stringify(input.validationSummary)])).rows[0]?.valid!==true)throw new NewDesignError("恢复演练时间或验证摘要无效。",422);if((await listRecordCards(client,"transfer_restore_drill",{where:{drill_operation_id:input.drillOperationId}})).length)throw new NewDesignError("恢复预检已经登记演练回执。",409);const row=await createRecordCard(client,{spaceId:String(drill.space_id),typeKey:"transfer_restore_drill",title:"恢复演练回执",values:{backup_operation_id:input.backupOperationId,drill_operation_id:input.drillOperationId,outcome:input.outcome,validation_summary:input.validationSummary,started_at:input.startedAt,completed_at:input.completedAt}});return{rows:[row]};})).rows[0];
  if(!row)throw new NewDesignError("恢复演练必须引用完整备份和已完成的恢复预检。",409);
  return mapRestoreDrill(row);
}

export async function allocateTransferStaging(input:{operationId:string;stagingKind:TransferStagingScope["stagingKind"]}):Promise<TransferStagingScope>{
  return tx(async client=>{
    const operation=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[input.operationId])).rows[0],"传输操作不存在。");
    if(operation.status!=="running")throw new NewDesignError("只有执行中的导入或恢复可以分配 staging。",409);
    const existing=(await listRecordCards(client,"transfer_staging_scope",{where:{operation_id:input.operationId},lock:true}))[0];
    if(existing){if(existing.staging_kind!==input.stagingKind)throw new NewDesignError("staging 类型与已登记范围不一致。",409);return mapStaging(existing);}
    return mapStaging(await createRecordCard(client,{spaceId:String(operation.space_id),typeKey:"transfer_staging_scope",title:"导入暂存范围",values:{operation_id:input.operationId,staging_kind:input.stagingKind,staging_key:operation.target_staging_key,status:"allocated",target_space_id:null,target_book_id:null,revision:1,published_at:null,abandoned_at:null}}));
  });
}

export async function advanceTransferStaging(id:string,input:{toStatus:"validating"|"ready_to_publish"|"published"|"abandoned";expectedRevision:number;targetSpaceId?:string|null;targetBookId?:string|null}):Promise<TransferStagingScope>{
  return tx(async client=>{
    const snapshot=await findRecordCard(client,id,"transfer_staging_scope");
    if(!snapshot)throw new NewDesignError("staging 不存在。",404);
    const operation=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 FOR UPDATE",[snapshot.operation_id])).rows[0],"传输操作不存在。");
    const current=await findRecordCard(client,id,"transfer_staging_scope",{lock:true});
    if(!current||Number(current.revision)!==input.expectedRevision)throw new NewDesignError("staging 已变化或不存在。",409);
    const allowed:Record<string,string[]>={allocated:["validating","abandoned"],validating:["ready_to_publish","abandoned"],ready_to_publish:["published","abandoned"]};
    if(!allowed[current.status]?.includes(input.toStatus))throw new NewDesignError("staging 不能进行此状态转换。",409);
    if(!["running","verifying"].includes(String(operation.status)))throw new NewDesignError("传输操作不在执行状态。",409);
    const targetSpaceId=current.target_space_id??input.targetSpaceId??null,targetBookId=current.target_book_id??input.targetBookId??null;
    if(current.target_space_id&&input.targetSpaceId&&current.target_space_id!==input.targetSpaceId||current.target_book_id&&input.targetBookId&&current.target_book_id!==input.targetBookId)throw new NewDesignError("staging 发布目标已冻结。",409);
    if(targetSpaceId&&!(await client.query("SELECT 1 FROM new_design.card_spaces WHERE id=$1",[targetSpaceId])).rowCount)throw new NewDesignError("目标空间不存在。",404);
    if(targetBookId&&!(await client.query("SELECT 1 FROM new_design.books WHERE id=$1 AND ($2::uuid IS NULL OR space_id=$2)",[targetBookId,targetSpaceId])).rowCount)throw new NewDesignError("目标小说与空间不一致。",409);
    return mapStaging(await replaceRecordCard(client,{id:current.recordCardId,spaceId:current.recordSpaceId,typeKey:"transfer_staging_scope",values:{...current,status:input.toStatus,target_space_id:targetSpaceId,target_book_id:targetBookId,revision:Number(current.revision)+1,published_at:input.toStatus==="published"?new Date().toISOString():null,abandoned_at:input.toStatus==="abandoned"?new Date().toISOString():null}}));
  });
}

export async function completeTransferOperation(id:string,input:{actor:string;manifestId:string}):Promise<TransferOperation>{
  return tx(async client=>{
    const current=assertFound((await client.query("SELECT * FROM new_design.transfer_operations WHERE id=$1 AND status='verifying' FOR UPDATE",[id])).rows[0],"传输操作不在验证状态。");
    if((await client.query("SELECT 1 FROM new_design.transfer_validations WHERE operation_id=$1 AND outcome IN ('failed','unavailable') LIMIT 1",[id])).rowCount)throw new NewDesignError("存在失败或不可用的验证项，不能发布。",409);
    const compatibility=(await client.query("SELECT outcome,unknown_required_capabilities FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_compatibility_snapshot' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,source_format_version integer,source_application_version text,current_application_version text,source_schema_version text,current_schema_version text,source_migration_hash char(64),current_migration_hash char(64),extension_versions jsonb,required_capabilities jsonb,missing_capabilities jsonb,unknown_required_capabilities jsonb,outcome text,detail text,checked_at timestamptz) WHERE record.status='active') transfer_compatibility_snapshot_record WHERE operation_id=$1 ORDER BY checked_at DESC LIMIT 1",[id])).rows[0];
    if(!compatibility||["incompatible","unavailable"].includes(String(compatibility.outcome))||(compatibility.unknown_required_capabilities as unknown[]).length>0)throw new NewDesignError("兼容性结果缺失或未通过。",409);
    if((await client.query("SELECT 1 FROM new_design.transfer_conflicts WHERE operation_id=$1 AND status IN ('pending','blocking') LIMIT 1",[id])).rowCount)throw new NewDesignError("仍有未解决冲突，不能发布。",409);
    if((await client.query("SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_step' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,step_key text,sort_order integer,status text,progress_completed bigint,progress_total bigint,checkpoint_key text,error_code text,error_summary text,revision integer,created_at timestamptz,started_at timestamptz,completed_at timestamptz) WHERE record.status='active') transfer_step_record WHERE operation_id=$1 AND status NOT IN ('succeeded','skipped') LIMIT 1",[id])).rowCount)throw new NewDesignError("仍有未完成的传输步骤。",409);
    const manifest=assertFound((await client.query("SELECT id FROM new_design.transfer_manifests WHERE id=$1 AND operation_id=$2",[input.manifestId,id])).rows[0],"操作清单不存在。");
    if(current.execution_mode==="execute"&&!(await client.query("SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_artifact' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,manifest_id uuid,artifact_kind text,media_type text,storage_locator text,normalized_case_locator text,display_filename text,checksum_algorithm text,checksum char(64),byte_size bigint,entry_count integer,compressed_bytes bigint,uncompressed_bytes bigint,status text,error_code text,created_at timestamptz,ready_at timestamptz) WHERE record.status='active') transfer_artifact_record WHERE operation_id=$1 AND manifest_id=$2 AND artifact_kind='package' AND status='ready' LIMIT 1",[id,manifest.id])).rowCount)throw new NewDesignError("没有通过校验的可下载包。",409);
    if(current.execution_mode==="dry_run"&&!(await client.query("SELECT 1 FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_artifact' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,manifest_id uuid,artifact_kind text,media_type text,storage_locator text,normalized_case_locator text,display_filename text,checksum_algorithm text,checksum char(64),byte_size bigint,entry_count integer,compressed_bytes bigint,uncompressed_bytes bigint,status text,error_code text,created_at timestamptz,ready_at timestamptz) WHERE record.status='active') transfer_artifact_record WHERE id=$1 AND operation_id=$2 AND status='ready'",[current.source_artifact_id,id])).rowCount)throw new NewDesignError("导入源包没有通过校验。",409);
    let status:TransferOperationStatus="ready",action:TransferOperationEvent["action"]="ready";
    if(current.execution_mode==="apply"){if(!(await listRecordCards(client,"transfer_import_source",{where:{operation_id:id}})).length)throw new NewDesignError("缺少冻结的导入来源。",409);status=current.operation_kind==="full_restore"?"restored":"imported";action=status==="restored"?"restore":"import";const staging=assertFound((await client.query("SELECT status FROM (SELECT fields.* FROM new_design.cards record JOIN new_design.card_types record_type ON record_type.id=record.card_type_id AND record_type.type_key='transfer_staging_scope' JOIN new_design.card_versions record_version ON record_version.id=record.current_version_id AND record_version.card_id=record.id CROSS JOIN LATERAL jsonb_to_record(record_version.values) AS fields(id uuid,operation_id uuid,staging_kind text,staging_key text,status text,target_space_id uuid,target_book_id uuid,revision integer,created_at timestamptz,published_at timestamptz,abandoned_at timestamptz) WHERE record.status='active') transfer_staging_scope_record WHERE operation_id=$1",[id])).rows[0],"缺少隔离 staging。");if(staging.status!=="published")throw new NewDesignError("staging 尚未显式发布。",409);}
    const revision=Number(current.revision)+1,row=(await client.query("UPDATE new_design.transfer_operations SET status=$2,ready_manifest_id=$3,revision=$4,completed_at=now(),current_step_key='' WHERE id=$1 RETURNING *",[id,status,input.manifestId,revision])).rows[0];
    await insertEvent(client,id,"verifying",status,action,input.actor,"清单、校验、兼容性和 staging 发布门禁均已通过。",revision);
    return mapOperation(row);
  });
}
